return ['project-id-version'=>'Lingua Forge 2.1.0','report-msgid-bugs-to'=>'https://wordpress.org/support/plugin/lingua-forge','last-translator'=>'admin','language-team'=>'Thai','mime-version'=>'1.0','content-type'=>'text/plain; charset=UTF-8','content-transfer-encoding'=>'8bit','pot-creation-date'=>'2026-06-01T15:14:22+00:00','po-revision-date'=>'2026-06-03 15:36+0000','x-generator'=>'Loco https://localise.biz/','x-domain'=>'lingua-forge','language'=>'th','plural-forms'=>'nplurals=1; plural=0;','x-loco-version'=>'2.8.5; wp-7.0; php-8.3.31','messages'=>['"%1$s %2$s" saved.'=>'"%1$s %2$s" บันทึกแล้ว','"%1$s" created. %2$d template updated.'=>'"%1$s" สร้างแล้ว. อัปเดตเทมเพลต %2$d รายการ' . "\0" . '','"%s" created.'=>'"%s" สร้างแล้ว','%d language not yet linked'=>'ยังไม่ได้เชื่อมโยง %d ภาษา' . "\0" . '','%d link updated.'=>'อัปเดตลิงก์ %d รายการ' . "\0" . '','%d locale pack installed.'=>'ติดตั้งแพ็คภาษาจำนวน %d แพ็ค' . "\0" . '','%d navigation reference updated.'=>'อัปเดตรายการอ้างอิงการนำทาง %d รายการ' . "\0" . '','%d part reference updated.'=>'อัปเดตรายการอ้างอิงส่วนเทมเพลต %d รายการ' . "\0" . '','%s Archive'=>'คลังข้อมูล: %s','(avg %.1f hits/block)'=>'(เฉลี่ย %.1f การเข้าถึง/บล็อก)','(avg %.1f hits/entry)'=>'(ค่าเฉลี่ย %.1f การเข้าถึง/รายการ)','(disabled)'=>'(ปิดการใช้งาน)','({skipped} had no replaceable links — re-scan to investigate)'=>'({skipped} ไม่มีลิงก์ที่สามารถแทนที่ได้ — สแกนใหม่เพื่อสอบสวน)','.txt file(s) in the directory'=>'.txt ไฟล์ในไดเรกทอรี','<strong>Lingua Forge:</strong> %1$d localized template(s) from the &#8220;%2$s&#8221; theme are preserved in the database but are currently inactive. They will become active again if you reactivate that theme. To carry your translations to the new theme, regenerate them via <strong>Settings → Lingua Forge → Router → FSE scaffold</strong>.'=>'<strong>Lingua Forge:</strong> %1$d เทมเพลตที่แปลแล้วจากธีม &#8220;%2$s&#8221; ถูกเก็บไว้ในฐานข้อมูลแต่ปัจจุบันยังไม่ทำงาน พวกมันจะกลับมาทำงานอีกครั้งเมื่อคุณเปิดใช้งานธีมนั้นอีกครั้ง เพื่อให้การแปลของคุณไปยังธีมใหม่ ให้สร้างใหม่ผ่าน <strong>การตั้งค่า → Lingua Forge → Router → FSE scaffold</strong>.','<strong>{n}</strong> auto-fixable link(s)'=>'<strong>{n}</strong> ลิงก์ที่แก้ไขอัตโนมัติได้','<strong>{n}</strong> link(s) needing manual review'=>'<strong>{n}</strong> ลิงก์ที่ต้องการการตรวจสอบด้วยตนเอง','<strong>{n}</strong> stale path(s)'=>'<strong>{n}</strong> เส้นทางเก่า','<strong>{n}</strong> template issue(s)'=>'<strong>{n}</strong> ปัญหาเทมเพลต','Accepts compiled .mo files only. Filename must follow the pattern {textdomain}-{locale}.mo. Uploading a file with the same name as an existing one will replace it.'=>'รับเฉพาะไฟล์ .mo ที่คอมไพล์แล้วเท่านั้น ชื่อไฟล์ต้องเป็นไปตามรูปแบบ {textdomain}-{locale}.mo การอัปโหลดไฟล์ที่มีชื่อเดียวกันกับไฟล์ที่มีอยู่จะเป็นการแทนที่ไฟล์เดิม','Action'=>'ดำเนินการ','Actions'=>'การดำเนินการ','active'=>'ใช้งานอยู่','Active Languages'=>'ภาษาที่ใช้งานอยู่','Active languages: add each language you want to support. Each language gets a URL prefix or subdomain and an hreflang tag in the page &lt;head&gt;.'=>'ภาษาใช้งานอยู่: เพิ่มภาษาที่คุณต้องการสนับสนุน แต่ละภาษาจะได้รับคำนำหน้าหรือซับโดเมน URL และแท็ก hreflang ในส่วน &lt;head&gt; ของหน้าเว็บ','Active Provider'=>'ผู้ให้บริการที่ใช้งานอยู่','Add entry'=>'เพิ่มรายการ','Add instructions to improve the draft — e.g. make it shorter, add a conclusion section, use a more formal register, include an FAQ block…'=>'เพิ่มคำแนะนำเพื่อปรับปรุงร่าง เช่น ทำให้สั้นลง เพิ่มส่วนสรุป ใช้ภาษาทางการมากขึ้น รวมคำถามที่พบบ่อย…','Add instructions to improve the draft — e.g. make it shorter, add a conclusion section, use a more formal register…'=>'เพิ่มคำแนะนำเพื่อปรับปรุงร่าง — เช่น ทำให้สั้นลง เพิ่มส่วนสรุป ใช้ระดับทางการมากขึ้น…','Add new entry'=>'เพิ่มรายการใหม่','Add one term per row. Both the source term and the target rendering are required. The language pair determines which translation jobs the constraint applies to.'=>'เพิ่มคำหนึ่งคำต่อแถว ทั้งคำต้นฉบับและการแสดงผลเป้าหมายจำเป็นต้องระบุ คู่ภาษากำหนดงานแปลที่คำสั่งนี้ใช้','Adds a link to the home page so visitors can browse in their language.'=>'เพิ่มลิงก์ไปยังหน้าแรกเพื่อให้ผู้เยี่ยมชมสามารถเรียกดูในภาษาของตนเอง','Administrators only (manage_options)'=>'เฉพาะผู้ดูแลระบบ (จัดการตัวเลือก)','After changing the primary language, flush permalinks (section below) for the URL routing to update.'=>'หลังจากเปลี่ยนภาษาหลักแล้ว ให้ล้าง permalinks (ส่วนด้านล่าง) เพื่ออัปเดตเส้นทาง URL','After changing URL structure settings (path prefix ↔ subdomain), always visit Settings → Permalinks and click Save Changes to flush the rewrite rules.'=>'หลังจากเปลี่ยนการตั้งค่าระบบ URL (คำนำหน้าเส้นทาง ↔ โดเมนย่อย) ให้เข้าไปที่ การตั้งค่า → ลิงก์ถาวร และคลิก บันทึกการเปลี่ยนแปลง เพื่อเคลียร์กฎการเขียนใหม่','AI Behaviour Preset'=>'ชุดพฤติกรรม AI','AI cache cleared. %d entry was removed.'=>'แคช AI ถูกล้างแล้ว %d รายการถูกลบออก' . "\0" . '','AI Cache: lists cached AI responses with hit counts. Clear the whole cache or a single post\'s entries. Use "Clear" before testing a translation change — cached results are returned even when you change the AI preset or model until the cache entry is evicted.'=>'แคช AI: รายการคำตอบ AI ที่แคชไว้พร้อมจำนวนการเข้าถึง ล้างแคชทั้งหมดหรือรายการโพสต์เดียว ใช้ "ล้าง" ก่อนทดสอบการเปลี่ยนแปล — ผลลัพธ์ที่แคชไว้จะถูกส่งคืนแม้เมื่อคุณเปลี่ยนการตั้งค่า AI หรือโมเดล จนกว่ารายการแคชจะถูกลบ','AI features are optional. Language routing, hreflang, the language switcher, and the translation group system all work without a provider configured.'=>'คุณสมบัติ AI เป็นตัวเลือก การกำหนดเส้นทางภาษา hreflang ตัวเปลี่ยนภาษา และระบบกลุ่มการแปล ทั้งหมดทำงานโดยไม่ต้องตั้งค่าผู้ให้บริการ','AI Limits & Security'=>'ขีดจำกัดและความปลอดภัยของ AI','AI provider returned an empty response.'=>'ผู้ให้บริการ AI ส่งคืนการตอบสนองว่างเปล่า','AI Usage'=>'การใช้งาน AI','Aim for 120–160 characters. Leave empty to use the excerpt fallback.'=>'ตั้งเป้าหมายไว้ที่ 120–160 ตัวอักษร ปล่อยว่างเพื่อใช้คำอธิบายย่อเป็นตัวเลือก','All time'=>'ตลอดเวลา','Allow editors to lock individual blocks'=>'อนุญาตให้บรรณาธิการล็อกบล็อกแต่ละอัน','Allow Gutenberg template-editing mode on post screens'=>'อนุญาตให้ใช้โหมดแก้ไขแม่แบบของ Gutenberg บนหน้าจอโพสต์','Also delete language assignments, translation relationships, meta descriptions, glossary, and Translation Memory when the plugin is uninstalled'=>'ลบการกำหนดภาษาความสัมพันธ์ในการแปล คำอธิบายเมตา คำศัพท์ และหน่วยความจำการแปลเมื่อถอนการติดตั้งปลั๊กอิน','Also generate meta description'=>'สร้างคำอธิบายเมตาเพิ่มเติม','Alternative (server-side):'=>'ทางเลือก (ฝั่งเซิร์ฟเวอร์):','An unknown error occurred.'=>'เกิดข้อผิดพลาดที่ไม่รู้จัก','and'=>'และ','Anthropic (Claude)'=>'Anthropic (Claude)','any'=>'ใดก็ได้','API calls saved by cache'=>'คำขอ API ที่ถูกบันทึกโดยแคช','API Key'=>'คีย์ API','API Keys'=>'คีย์ API','API Keys Tab'=>'แท็บคีย์ API','API Response Cache'=>'แคชคำตอบ API','Applied ✓'=>'นำไปใช้แล้ว ✓','Apply failed — please try again.'=>'การนำไปใช้ล้มเหลว — กรุณาลองใหม่อีกครั้ง','Apply to Block'=>'นำไปใช้กับบล็อก','Apply to Editor'=>'นำไปใช้กับบรรณาธิการ','Apply to Footnote'=>'สมัครใช้งานในเชิงอรรถ','Apply to Meta Description'=>'ใช้กับคำอธิบายเมตา','Apply translation'=>'นำการแปลไปใช้','Applying…'=>'กำลังนำไปใช้…','Approximate size'=>'ขนาดประมาณ','Archive'=>'คลังข้อมูล','Archive: %s'=>'คลังข้อมูล: %s','Authors and above (edit_published_posts)'=>'ผู้เขียนและระดับสูงกว่า (แก้ไขโพสต์ที่เผยแพร่แล้ว)','Behavior'=>'พฤติกรรม','Behavior: choose the AI preset (Literal, Balanced, Creative), add site-wide custom prompt instructions, enable or disable automatic post-save translation, and configure the Translation Memory.'=>'พฤติกรรม: เลือกการตั้งค่า AI (Literal, Balanced, Creative) เพิ่มคำสั่งแนะนำแบบกำหนดเองทั่วไซต์ เปิดหรือปิดการแปลอัตโนมัติหลังบันทึกโพสต์ และกำหนดค่าหน่วยความจำการแปล','Block Content'=>'เนื้อหาบล็อก','block descriptionRenders a polite notice when the current page is being shown in its source language because no translation exists for the visitor\'s language. Driven by the Lingua Forge router\'s LINGUAFORGE_LANG_FALLBACK_ACTIVE signal — emits nothing when a translation exists for the request locale.'=>'แสดงข้อความสุภาพเมื่อหน้าเว็บปัจจุบันแสดงในภาษาต้นทางเนื่องจากไม่มีการแปลสำหรับภาษาของผู้เยี่ยมชม ซึ่งขับเคลื่อนโดยสัญญาณ LINGUAFORGE_LANG_FALLBACK_ACTIVE ของตัวเรนเดอร์ Lingua Forge — จะไม่ส่งอะไรเมื่อมีการแปลสำหรับภาษาที่ร้องขอ','Block Editor'=>'ตัวแก้ไขบล็อก','block keywordfallback'=>'การล้มเหลว','block keywordi18n'=>'i18n','block keywordlanguage'=>'ภาษา','block keywordlinguaforge'=>'linguaforge','block keywordtranslation'=>'การแปล','Block locking'=>'การล็อกบล็อก','Block patterns registered for custom post types. Use the Translate button to produce a language variant. The translated content is saved here and can be copied into any CPT post from the block editor Pattern inserter or used as a starting point for a Synced Pattern (Reusable Block).'=>'รูปแบบบล็อกที่ลงทะเบียนสำหรับประเภทโพสต์แบบกำหนดเอง ใช้ปุ่มแปลเพื่อสร้างเวอร์ชันภาษาที่แตกต่างกัน เนื้อหาที่แปลจะถูกบันทึกไว้ที่นี่และสามารถคัดลอกไปยังโพสต์ CPT ใดก็ได้จากตัวแทรกเทมเพลตบล็อกหรือใช้เป็นจุดเริ่มต้นสำหรับเทมเพลตที่ซิงค์กัน (Reusable Block)','block titleMissing Translation Notice'=>'แจ้งเตือนการแปลที่ขาดหาย','Block translation reuses'=>'การใช้ซ้ำการแปลบล็อก','Block-level translation cache shared across posts. When enabled, identical blocks (same markup, language pair, and glossary) are served from memory instead of calling the AI again. Configure in Settings → Behavior.'=>'แคชการแปลบล็อกระดับบล็อกที่แชร์กันระหว่างโพสต์ เมื่อเปิดใช้งาน บล็อกที่เหมือนกัน (เครื่องหมายเดียวกัน คู่ภาษากรณีเดียวกัน และพจนานุกรม) จะถูกเรียกจากหน่วยความจำแทนที่จะเรียก AI ใหม่ กำหนดค่าใน การตั้งค่า → พฤติกรรม','Browser language redirect'=>'เปลี่ยนเส้นทางภาษาของเบราว์เซอร์','Built-in preset instructions:'=>'คำแนะนำ preset ในตัว:','Bulletize (•-prefixed)'=>'ทำเป็นหัวข้อย่อย (ขึ้นต้นด้วย •)','Cache translated equivalents at the block level so reusable content (shared footers, sidebars, accordions, boilerplate-heavy legal sections) does not pay an API call every time. When enabled, the translation flow parses each post into blocks, looks each block up in the cache, and sends only uncached blocks to the AI in a single batched request. Glossary edits and Compliance preset changes automatically invalidate affected cached translations. View statistics and clear the cache under Maintenance.'=>'แคชคำแปลที่เทียบเท่าในระดับบล็อกเพื่อให้เนื้อหาที่ใช้ซ้ำได้ (ส่วนท้ายร่วม แถบด้านข้าง คำอธิบายแบบพับได้ ส่วนกฎหมายที่มีเทมเพลตมาก) ไม่ต้องเรียก API ทุกครั้ง เมื่อเปิดใช้งาน การไหลของการแปลจะแยกโพสต์แต่ละโพสต์เป็นบล็อก ค้นหาแต่ละบล็อกในแคช และส่งบล็อกที่ไม่ได้แคชไปยัง AI ในคำขอแบบกลุ่มเดียวกัน การแก้ไขคำศัพท์และการเปลี่ยนแปลงการตั้งค่าความสอดคล้องจะเป็นการยกเลิกการแคชคำแปลที่ได้รับผลกระทอโดยอัตโนมัติ ดูสถิติและล้างแคชในส่วนบำรุงรักษา','cached'=>'แคชไว้แล้ว','Cached API responses'=>'คำตอบ API ที่แคชไว้','Cached block translations'=>'การแปลบล็อกที่แคชไว้','Cancel'=>'ยกเลิก','Cannot determine target language from slug.'=>'ไม่สามารถกำหนดภาษาปลายทางจาก slug ได้','Cap how much AI usage the site can generate and restrict which user roles may trigger paid AI calls. Sits on top of the per-user rate limit (30 requests / minute, hardcoded) that already protects against single-user runaway loops.'=>'กำหนดขีดสูงสุดของการใช้งาน AI ที่เว็บไซต์สามารถสร้างได้และจำกัดบทบาทผู้ใช้ที่สามารถเรียกใช้การโทร AI แบบชำระเงิน ซึ่งอยู่บนสุดของขีดจำกัดอัตราต่อผู้ใช้ (30 คำขอ / นาที, กำหนดไว้ล่วงหน้า) ซึ่งป้องกันไม่ให้ลูปที่ลื่นไหลของผู้ใช้เดียวกันเกิดขึ้น','chars'=>'อักขระ','Chunk translated'=>'ส่วนที่แปลแล้ว','Chunk translated to:'=>'ส่วนที่แปลเป็น: ','Clear'=>'ล้าง','Clear All'=>'ล้างทั้งหมด','Clear all cached AI results? Future requests will trigger fresh API calls until the cache rebuilds.'=>'ล้างผลลัพธ์ AI ที่แคชไว้ทั้งหมดหรือไม่? คำขอในอนาคตจะเรียก API ใหม่จนกว่าจะแสดงผลแคชใหม่','Clear API Response Cache'=>'ล้างแคชคำตอบ API','Clear Debug Files'=>'ล้างไฟล์ดีบัก','Clear hints'=>'ล้างคำแนะนำ','Clear input'=>'ล้างข้อมูลนำเข้า','Clear the entire Translation Memory? Future translations will rebuild the cache as they run.'=>'ล้างหน่วยความจำการแปลทั้งหมดไหม? การแปลในอนาคตจะสร้างแคชใหม่ตามลำดับ','Clear Translation Memory'=>'ล้างหน่วยความจำการแปล','Close'=>'ปิด','Close language panel'=>'ปิดแผงภาษา','Close popover'=>'ปิดป็อปอัป','Compliance Preset'=>'การตั้งค่าความสอดคล้อง','Content generated'=>'เนื้อหาถูกสร้างขึ้นแล้ว','Content Generator'=>'เครื่องมือสร้างเนื้อหา','Content ready'=>'เนื้อหาพร้อมแล้ว','Contributors and above — default (edit_posts)'=>'ผู้ร่วมเขียนและระดับสูงกว่า — ค่าเริ่มต้น (แก้ไขโพสต์)','Control how much content is sent to the AI and how large the response can be. Leave a field blank to use the built-in default (shown as placeholder). Raise these values if large pages are being cut off; lower them to reduce API costs.'=>'ควบคุมปริมาณเนื้อหาที่ส่งไปยัง AI และขนาดของคำตอบที่สามารถรับได้ ปล่อยว่างไว้เพื่อใช้ค่ามาตรฐานในตัว (แสดงเป็นตัวอย่าง) เพิ่มค่านี้หากหน้าเว็บขนาดใหญ่มักถูกตัดออก ลดค่านี้เพื่อลดต้นทุน API','Controls the token budget and input limits for the AI Content Generator feature. Leave fields blank to use the built-in defaults.'=>'ควบคุมงบประมาณโทเค็นและขีดจำกัดการป้อนข้อมูลสำหรับคุณสมบัติ AI Content Generator ปล่อยช่องว่างไว้เพื่อใช้ค่าเริ่มต้นในตัว','Controls what happens when an administrator deletes the plugin from Plugins → Installed Plugins → Delete. Plugin settings and AI caches are always removed. Language assignments and translation relationships are kept by default so an accidental uninstall or a reinstall can pick up where it left off.'=>'ควบคุมสิ่งที่จะเกิดขึ้นเมื่อผู้ดูแลระบบลบปลั๊กอินออกจาก Plugins → ติดตั้งปลั๊กอิน → ลบ การตั้งค่าปลั๊กอินและแคช AI จะถูกลบเสมอ การกำหนดภาษากับความสัมพันธ์ในการแปลจะถูกเก็บไว้เป็นค่าเริ่มต้นเพื่อให้การถอนการติดตั้งหรือการติดตั้งใหม่สามารถดำเนินต่อไปได้จากจุดที่หยุดไว้','Conversational'=>'สนทนา','Copied ✓'=>'คัดลอกแล้ว ✓','Copy'=>'คัดลอก','Copy markup'=>'คัดลอกโค้ดมาร์กอัป','Copy the result and paste it wherever needed (e.g. directly into the footnote field).'=>'คัดลอกผลลัพธ์และวางในที่ที่ต้องการ (เช่น โดยตรงในช่องอรรถาธิบายประกอบ)','Copy to safe storage'=>'คัดลอกไปยังที่เก็บปลอดภัย','Could not add entry: source term and target term are required.'=>'ไม่สามารถเพิ่มรายการได้: ต้องระบุคำต้นทางและคำปลายทาง','Could not copy the file. Check that the uploads folder is writable.'=>'ไม่สามารถคัดลอกไฟล์ได้ ตรวจสอบให้แน่ใจว่าโฟลเดอร์ uploads สามารถเขียนได้','Could not instantiate the provider.'=>'ไม่สามารถสร้างอินสแตนซ์ของผู้ให้บริการได้','Could not save the file. Check that the uploads folder is writable.'=>'ไม่สามารถบันทึกไฟล์ได้ ตรวจสอบให้แน่ใจว่าโฟลเดอร์ uploads สามารถเขียนได้','Could not save the glossary entry.'=>'ไม่สามารถบันทึกข้อมูลคำศัพท์ได้','CPT Block Patterns'=>'รูปแบบบล็อก CPT','Create'=>'สร้าง','Create missing'=>'สร้างที่ขาดหาย','Creating translations for post type "%s" requires an active integration. Please ensure the required integration is installed and active.'=>'การสร้างการแปลสำหรับประเภทโพสต์ "%s" ต้องมีการเชื่อมต่อที่ใช้งานอยู่ กรุณาตรวจสอบให้แน่ใจว่าการเชื่อมต่อที่จำเป็นติดตั้งและเปิดใช้งานแล้ว','Creating…'=>'กำลังสร้าง…','Creative / Marketing'=>'สร้างสรรค์ / การตลาด','Creative / Marketing instructions'=>'คำแนะนำด้านความคิดสร้างสรรค์ / การตลาด','Current content (will be overwritten)'=>'เนื้อหาปัจจุบัน (จะถูกเขียนทับ)','Current title'=>'หัวข้อปัจจุบัน','Current: {current}'=>'ปัจจุบัน: {current}','Currently inherited from the %s constant. Selecting a value here will override it.'=>'ในปัจจุบันสืบทอดมาจากค่าคงที่ %s การเลือกค่าที่นี่จะโอเวอร์ไรท์มัน','Currently skipped for posts that use block-comment attribute placeholders (wp:details summary fields, etc.) — they fall through to the existing single-call translation path.'=>'ปัจจุบันข้ามสำหรับโพสต์ที่ใช้ตัวดำเนินการแทนที่ attribute ของบล็อก (เช่น wp:details, ฟิลด์คำอธิบายสรุป ฯลฯ) — พวกเขาจะผ่านไปยังเส้นทางการแปลแบบเรียกเดียวที่มีอยู่เดิม','Currently:'=>'ปัจจุบัน:','Custom'=>'กำหนดเอง','Daily AI quota reached (%1$d requests). Resets at %2$s UTC.'=>'โควต้าการใช้งาน AI รายวันเต็มแล้ว (%1$d คำขอ) รีเซ็ตเวลา %2$s UTC','Daily request limit'=>'ขีดจำกัดคำขอรายวัน','Debug Files'=>'ไฟล์ดีบัก','Debug files cleared. %d file was removed.'=>'ไฟล์ดีบักถูกล้างแล้ว %d ไฟล์ถูกลบออก' . "\0" . '','Debug logging'=>'การบันทึกบันทึกการดีบัก','Debug logging disabled.'=>'การบันทึกบันทึกการดีบักถูกปิดใช้งาน','Debug logging enabled.'=>'เปิดใช้งานการบันทึกดีบัก','Debug: enable the debug log to capture AI prompts and API responses to a local file. Disable after troubleshooting — debug mode writes a file on every AI request.'=>'ดีบัก: เปิดใช้งานบันทึกดีบักเพื่อจับคำสั่ง AI และคำตอบ API ไปยังไฟล์ในเครื่อง ปิดหลังจากการแก้ปัญหา — โหมดดีบักจะเขียนไฟล์ในทุกคำขอ AI','Delete'=>'ลบ','Delete all .txt files in the debug directory? The directory itself will remain so future debug writes still land cleanly.'=>'ลบไฟล์ .txt ทั้งหมดในไดเรกทอรีดีบักไหม? ไดเรกทอรีจะยังคงอยู่เพื่อให้การเขียนดีบักในอนาคตยังคงทำงานได้','Delete all files for this override (both .mo and .po)?'=>'ลบไฟล์ทั้งหมดสำหรับการแทนที่นี้ (ทั้ง .mo และ .po) หรือไม่','Delete content data on uninstall'=>'ลบข้อมูลเนื้อหาเมื่อถอนการติดตั้งไหม','Delete this glossary entry?'=>'ต้องการลบรายการคำศัพท์นี้หรือไม่','Describe what to write — topic, key points, structure…'=>'อธิบายสิ่งที่ต้องการเขียน — หัวข้อ จุดสำคัญ โครงสร้าง…','Directory'=>'ไดเรกทอรี','Disable during prompt tuning or when you need every request to reach the AI provider. Disabling does not delete cached entries — re-enabling restores them. Increasing API spend immediately on busy sites is expected when disabled.'=>'ปิดใช้งานในระหว่างการปรับแต่งคำสั่งหรือเมื่อคุณต้องการให้คำขอทุกคำไปถึงผู้ให้บริการ AI การปิดใช้งานจะไม่ลบรายการแคช — การเปิดใช้งานใหม่จะกู้คืนรายการเหล่านั้น การเพิ่มงบประมาณ API ทันทีบนเว็บไซต์ที่ใช้งานหนาแน่นเป็นสิ่งที่คาดหวังเมื่อปิดใช้งาน','Display'=>'การแสดงผล','Displays the Lingua Forge language switcher.'=>'แสดงตัวสลับภาษา Lingua Forge','Documentation'=>'เอกสาร','Done'=>'เสร็จสิ้น','Done — {done} of {total} post(s) fixed.'=>'เสร็จแล้ว — แก้ไขแล้ว {done} จาก {total} โพสต์','Down'=>'ลงล่าง','Download and install a WordPress core language pack directly from WordPress.org. Once installed, the locale becomes available for URL routing and the AI translation workflow. The list of available languages is fetched on demand — click the button below to load it.'=>'ดาวน์โหลดและติดตั้งแพ็คภาษาหลักของ WordPress โดยตรงจาก WordPress.org เมื่อทำการติดตั้งแล้ว ภาษานั้นจะสามารถใช้งานสำหรับการ routing URL และ workflow การแปล AI รายการภาษาที่สามารถใช้งานได้จะถูกดึงข้อมูลตามคำขอ — คลิกปุ่มด้านล่างเพื่อโหลด','Dropdown direction'=>'ทิศทางของเมนูดรอปดาวน์','Editors and above (edit_others_posts)'=>'บรรณาธิการและระดับสูงกว่า (แก้ไขโพสต์ของผู้อื่น)','Enable API response caching'=>'เปิดใช้งานการแคชคำตอบ API','Enable block-level translation cache reuse across posts'=>'เปิดใช้งานการใช้ซ้ำแคชการแปลในระดับบล็อกข้ามโพสต์','Enter your API key for at least one AI provider. Keys are encrypted at rest using AES-256-GCM with a site-specific secret (LINGUAFORGE_SECRET). Do not share database exports without rotating the secret first.'=>'ป้อนคีย์ API ของคุณสำหรับผู้ให้บริการ AI อย่างน้อยหนึ่งราย คีย์จะถูกเข้ารหัสในที่เก็บข้อมูลโดยใช้ AES-256-GCM พร้อมความลับเฉพาะไซต์ (LINGUAFORGE_SECRET) ห้ามแชร์การส่งออกฐานข้อมูลโดยไม่หมุนเวียนความลับก่อน','environment variable'=>'ตัวแปรสิ่งแวดล้อม','Error'=>'ข้อผิดพลาด','Expand'=>'ขยายความ','Expected: {expected}'=>'คาดหวัง: {expected}','Extra guidance — tone, style, constraints, target audience…'=>'คำแนะนำเพิ่มเติม — โทนเสียง สไตล์ ข้อจำกัด กลุ่มเป้าหมาย…','Extra guidance — tone, style, constraints…'=>'คำแนะนำเพิ่มเติม — โทนเสียง สไตล์ ข้อจำกัด…','Failed. Please try again.'=>'ล้มเหลว กรุณาลองใหม่อีกครั้ง','Feature'=>'คุณสมบัติ','Features are grouped into two tiers. Enter the exact model identifier for each tier and provider. Leave a field blank to use the built-in default (shown as placeholder). Only the active provider\'s models are called at runtime — configure the others in advance if you plan to switch.'=>'คุณสมบถูกรวมเป็นสองระดับ ป้อนรหัสโมเดลที่แน่นอนสำหรับแต่ละระดับและผู้ให้บริการ ปล่อยช่องว่างไว้เพื่อใช้ค่าเริ่มต้นในตัว (แสดงเป็นตัวอย่าง) เฉพาะโมเดลของผู้ให้บริการที่ใช้งานอยู่เท่านั้นที่จะถูกเรียกใช้ในเวลารัน — ตั้งค่าโมเดลของผู้อื่นล่วงหน้าหากคุณวางแผนที่จะเปลี่ยน','File copied to safe storage successfully.'=>'คัดลอกไฟล์ไปยังที่เก็บปลอดภัยสำเร็จแล้ว','Files'=>'ไฟล์','Files land in the directory below. Useful for diagnosing translation issues — turn off once you have what you need so the files do not accumulate. You can also force this from wp-config.php with `define( \'LINGUAFORGE_AI_DEBUG\', true );` which overrides the toggle.'=>'ไฟล์จะถูกบันทึกในไดเรกทอรีด้านล่าง ซึ่งมีประโยชน์สำหรับการวินิจฉัยปัญหาการแปล — ปิดการใช้งานเมื่อคุณได้สิ่งที่ต้องการเพื่อไม่ให้ไฟล์สะสม คุณยังสามารถบังคับได้จาก wp-config.php ด้วย `define( \'LINGUAFORGE_AI_DEBUG\', true );` ซึ่งจะลบล้างการเปิดปิดนี้','Filter'=>'ตัวกรอง','Filter with linguaforge_debug_dir to redirect debug output to a non-public location.'=>'กรองด้วย linguaforge_debug_dir เพื่อเปลี่ยนเส้นทางผลลัพธ์การดีบักไปยังตำแหน่งที่ไม่เปิดเผย','Fix'=>'แก้ไข','Fix All'=>'แก้ไขทั้งหมด','Fix all links'=>'แก้ไขลิงก์ทั้งหมด','Fix all parts'=>'แก้ไขส่วนประกอบทั้งหมด','Fix Links'=>'แก้ไขลิงก์','Fix Nav'=>'แก้ไขเมนูนำทาง','Fix Parts'=>'แก้ไขส่วนประกอบ','Fix Template'=>'แก้ไขเทมเพลต','Fixing {n} / {total}…'=>'กำลังแก้ไข {n} / {total}…','Fixing…'=>'กำลังแก้ไข…','Flush Permalink Rules'=>'ล้างกฎ Permalink','Flush Permalinks'=>'ล้างข้อมูล Permalinks','Footnote Content'=>'เนื้อหาอรรถาธิบายประกอบ','footnote(s) translated — applied together with content.'=>'อรรถาธิบายประกอบที่แปลแล้ว — นำไปใช้ร่วมกับเนื้อหา','Footnotes'=>'อรรถาธิบายประกอบ','Footnotes payload (advanced)'=>'ข้อมูลอ้างอิงเชิงอรรถ (ขั้นสูง)','Forbidden'=>'ห้ามเข้าใช้','Forced OFF by the LINGUAFORGE_AI_DEBUG constant in wp-config.php. Remove that line to control this toggle from here.'=>'บังคับปิดโดยค่าคงที่ LINGUAFORGE_AI_DEBUG ใน wp-config.php ลบบรรทัดนั้นเพื่อควบคุมการเปิดปิดนี้จากที่นี่','Forced ON by the LINGUAFORGE_AI_DEBUG constant in wp-config.php. Remove that line to control this toggle from here.'=>'บังคับเปิดโดยค่าคงที่ LINGUAFORGE_AI_DEBUG ใน wp-config.php ลบบรรทัดนั้นเพื่อควบคุมการเปิดปิดนี้จากที่นี่','Found {parts} across <strong>{total}</strong> of <strong>{scanned}</strong> scanned post(s) for <strong>{lang}</strong>.'=>'พบ {parts} ใน <strong>{total}</strong> จากโพสต์ที่สแกนแล้ว <strong>{scanned}</strong> โพสต์ สำหรับ <strong>{lang}</strong>.','From'=>'จาก','Front Page'=>'หน้าแรก','FSE localisation: scaffold, translate, and fix links in Full Site Editing templates and template parts directly from this tab.'=>'การแปลภาษา FSE: สร้างโครงร่าง แปล และแก้ไขลิงก์ในเทมเพลตและส่วนประกอบเทมเพลตของ Full Site Editing โดยตรงจากแท็บนี้','FSE templates seeded from the active theme. Create then customise in the Site Editor.'=>'เทมเพลต FSE ที่สร้างจากธีมที่ใช้งานอยู่ สร้างแล้วปรับแต่งในตัวแก้ไขไซต์','Full Article'=>'บทความเต็ม','Full post'=>'โพสต์เต็ม','General'=>'ทั่วไป','Generate'=>'สร้าง','Generate Content'=>'สร้างเนื้อหา','Generate content…'=>'สร้างเนื้อหา…','Generate Excerpt'=>'สร้างตัวอย่างย่อ','Generate Meta Description'=>'สร้างคำอธิบายเมตา','Generated Content'=>'เนื้อหาที่สร้างขึ้น','Generated meta description'=>'คำอธิบายเมตาที่สร้างขึ้น','Generating…'=>'กำลังสร้าง…','Generation failed.'=>'การสร้างล้มเหลว','Getting started'=>'เริ่มต้นใช้งาน','Global AI preset'=>'การตั้งค่าทั่วโลกของ AI','Global default (%s)'=>'ค่าเริ่มต้นทั่วโลก (%s)','Glossary'=>'คำศัพท์','Glossary entry added.'=>'เพิ่มรายการคำศัพท์แล้ว','Glossary entry removed.'=>'ลบรายการคำศัพท์แล้ว','Glossary Tab'=>'แท็บคำศัพท์','Google (Gemini)'=>'Google (Gemini)','Hide'=>'ซ่อน','Hints'=>'คำแนะนำ','Home link text'=>'ข้อความลิงก์หน้าแรก','How it should appear in the translation. Type the same value as the source term to instruct the AI to preserve it verbatim.'=>'วิธีที่ควรปรากฏในคำแปล พิมพ์ค่าที่เหมือนกับคำศัพท์ต้นฉบับเพื่อสั่งให้ AI คงไว้ตามคำ','https://github.com/leotiger/lingua-forge'=>'https://github.com/leotiger/lingua-forge','https://lingua-forge.com'=>'https://lingua-forge.com','Icon + label'=>'ไอคอน + ป้ายชื่อ','Icon only'=>'ไอคอนเท่านั้น','If checked, uninstalling the plugin will permanently delete all language assignments, translation relationships, meta descriptions, per-page presets, the AI glossary, and Translation Memory for every post on this site. This cannot be undone. Leave unchecked unless you are fully removing multilingual support from the site.'=>'ถ้าเลือก การถอนการติดตั้งปลั๊กอินจะลบการกำหนดภาษาความสัมพันธ์ในการแปล คำอธิบายเมตา คำศัพท์และหน่วยความจำการแปลทั้งหมดอย่างถาวร ซึ่งไม่สามารถกู้คืนได้ ยกเว้นคุณจะลบการสนับสนุนหลายภาษาออกจากเว็บไซต์','Improve writing'=>'ปรับปรุงการเขียน','Informative'=>'ให้ข้อมูล','Input tokens'=>'โทเค็นเข้า','Install'=>'ติดตั้ง','Install a Language'=>'ติดตั้งภาษา','Installing…'=>'กำลังติดตั้ง…','Instructions (optional)'=>'คำแนะนำ (ไม่บังคับ)','Instructions / key points'=>'คำแนะนำ / จุดสำคัญ','Integration API'=>'API การรวม','Internal Link Fixer'=>'ตัวแก้ไขลิงก์ภายใน','Introduction only'=>'เฉพาะบทนำ','Invalid file reference.'=>'อ้างอิงไฟล์ไม่ถูกต้อง','Invalid filename.'=>'ชื่อไฟล์ไม่ถูกต้อง','Invalid language.'=>'ภาษาไม่ถูกต้อง','Invalid locale code.'=>'รหัสภาษาที่ไม่ถูกต้อง','Invalid or primary language.'=>'ภาษาไม่ถูกต้องหรือเป็นภาษาเริ่มต้น','Invalid post type.'=>'ประเภทโพสต์ไม่ถูกต้อง','Invalid template part.'=>'ส่วนเทมเพลตไม่ถูกต้อง','Invalid template type.'=>'ประเภทเทมเพลตไม่ถูกต้อง','Key points, ideas, or structure to build from…'=>'จุดสำคัญ ไอเดีย หรือโครงสร้างที่จะสร้างจาก…','Keys are encrypted with AES-256-CBC before being stored in the WordPress database. The encryption secret is derived from your WordPress auth salts (wp-config.php), so plaintext keys never touch the database.'=>'คีย์ API ถูกเข้ารหัสด้วย AES-256-CBC ก่อนจัดเก็บในฐานข้อมูล WordPress คีย์ลับการเข้ารหัสได้มาจากเกลือการรับรองความถูกต้องของ WordPress ของคุณ (wp-config.php) ดังนั้นคีย์ข้อความธรรมดาจะไม่สัมผัสกับฐานข้อมูล','Language'=>'ภาษา','Language %s installed successfully.'=>'ติดตั้งภาษา %s สำเร็จแล้ว','Language (optional)'=>'ภาษา (ตัวเลือก)','Language installation is disabled on this server (DISALLOW_FILE_MODS is set).'=>'การติดตั้งภาษาได้รับการปิดใช้งานบนเซิร์ฟเวอร์นี้ (DISALLOW_FILE_MODS ถูกตั้งค่า)','Language installation is disabled on this server. The DISALLOW_FILE_MODS constant is set in wp-config.php. Install language packs manually via WP-CLI: wp language core install de_DE'=>'การติดตั้งภาษาได้รับการปิดใช้งานบนเซิร์ฟเวอร์นี้ ค่าคงที่ DISALLOW_FILE_MODS ถูกตั้งค่าใน wp-config.php ติดตั้งแพ็คภาษาด้วยตนเองผ่าน WP-CLI: wp language core install de_DE','Language label'=>'ป้ายภาษาสำหรับแสดงผล','Language Overrides'=>'การตั้งค่าภาษาแทนที่','Language Overrides: manage custom .po/.mo override files for the Lingua Forge UI strings. Use this instead of editing plugin files directly — overrides survive updates.'=>'การเปลี่ยนแปลงภาษา: จัดการไฟล์ .po/.mo ที่กำหนดเองสำหรับข้อความ UI ของ Lingua Forge ใช้แทนการแก้ไขไฟล์ปลั๊กอินโดยตรง — การเปลี่ยนแปลงจะอยู่รอดการอัปเดต','Language pack installation failed. The language may already be installed, the locale code may be incorrect, or your server may block file writes.'=>'การติดตั้งแพ็คภาษาล้มเหลว ภาษาอาจติดตั้งแล้ว รหัสภาษาผิด หรือเซิร์ฟเวอร์ของคุณบล็อกการเขียนไฟล์','Language Setup'=>'การตั้งค่าภาษา','Language Switcher'=>'สลับภาษา','Language switcher'=>'ตัวเปลี่ยนภาษา','Language-specific copies of the theme\'s template parts. Once scaffolded, templates are updated to reference the language-specific part.'=>'สำเนาเทมเพลตของธีมตามภาษาที่เฉพาะเจาะจง เมื่อสร้างเสร็จแล้ว เทมเพลตจะอัปเดตเพื่ออ้างอิงส่วนประกอบภาษานั้น','Language:'=>'ภาษา:','Languages currently known to the router (derived from installed WordPress locale packs plus the primary language). Install additional language packs in the section below to make more languages available for routing and translation.'=>'ภาษาที่รู้จักในตอนนี้จาก router (อ้างอิงจากแพ็คภาษาของ WordPress ที่ติดตั้งและภาษาหลัก) ติดตั้งแพ็คภาษิเพิ่มเติมด้านล่างเพื่อให้สามารถใช้งานภาษาเพิ่มเติมสำหรับการ routing และการแปล','Last 30 days'=>'30 วันที่ผ่านมา','Last 7 days'=>'7 วันที่ผ่านมา','Lead paragraph (≤60 w)'=>'ย่อหน้าแนะนำ (≤60 คำ)','Leave a model field blank to use the built-in default for that tier. The placeholder text shows which model will be used.'=>'ปล่อยให้ช่องโมเดลว่างไว้เพื่อใช้ค่าเริ่มต้นในระดับนั้น ข้อความตัวอย่างแสดงว่าโมเดลใดจะถูกใช้','Leave blank for brand names and language-agnostic terms that should be enforced regardless of which language we are translating from.'=>'เว้นว่างไว้สำหรับชื่อแบรนด์และคำศัพท์ที่ไม่ขึ้นกับภาษา ซึ่งควรบังคับใช้ไม่ว่าจะเป็นภาษาใดที่เรากำลังแปลจาก','Leave blank to apply this entry to all target languages — ideal for brand names, abbreviations, and terms that must be preserved verbatim in every translation.'=>'เว้นว่างไว้เพื่อใช้รายการนี้กับทุกภาษาเป้าหมาย — เหมาะสำหรับชื่อแบรนด์ คำย่อ และคำศัพท์ที่ต้องคงไว้ตามคำในทุกคำแปล','Leave blank to keep the existing key. Enter a new value to replace it.'=>'ปล่อยว่างไว้เพื่อรักษาคีย์เดิม ใส่ค่าที่ใหม่เพื่อแทนที่','Leave blank to use the built-in default. Clearing a saved override restores the default on next save.'=>'ปล่อยว่างเพื่อใช้ค่าเริ่มต้นในตัว การลบการโอเวอร์ไรท์ที่บันทึกไว้จะคืนค่าเริ่มต้นในการบันทึกครั้งถัดไป','Legal / Compliance'=>'กฎหมาย / การปฏิบัติตาม','Legal / Compliance instructions'=>'คำแนะนำด้านกฎหมาย / การปฏิบัติตาม','Light'=>'เบา','Light (default — fast and cost-effective)'=>'เบา (ค่าเริ่มต้น — รวดเร็วและคุ้มค่า)','Light (fast and cost-effective — Haiku / Flash)'=>'เบา (รวดเร็วและคุ้มค่า — Haiku / Flash)','Light: used for meta descriptions and excerpt generation — fast, low cost.'=>'แสง: ใช้สำหรับคำอธิบายเมตาและการสร้างตัวอย่างอย่างรวดเร็ว — รวดเร็ว ต้นทุนต่ำ','Limit results to pages in the given Lingua Forge language code.'=>'จำกัดผลลัพธ์เฉพาะหน้าที่อยู่ในรหัสภาษาของ Lingua Forge ที่กำหนด','Limits'=>'ขีดจำกัด','Lingua Forge'=>'Lingua Forge','Lingua Forge adds multilingual routing, AI-powered translation, hreflang SEO tags, and a language switcher to your WordPress site.'=>'Lingua Forge เพิ่มเส้นทางหลายภาษา การแปลด้วย AI แท็ก SEO hreflang และตัวเปลี่ยนภาษาให้กับเว็บไซต์ WordPress ของคุณ','Lingua Forge AI Tools'=>'เครื่องมือ AI ของ Lingua Forge','Lingua Forge restricts two Gutenberg features by default to keep editorial behavior consistent across languages. Opt in here when you need full Gutenberg / FSE capabilities.'=>'Lingua Forge จำกัดคุณสมบัติ Gutenberg สองอย่างเป็นค่าเริ่มต้นเพื่อรักษาพฤติกรรมการแก้ไขให้สอดคล้องกันในทุกภาษา เลือกใช้งานที่นี่เมื่อคุณต้องการความสามารถเต็มรูปแบบของ Gutenberg / FSE','Lingua Forge Settings'=>'การตั้งค่า Lingua Forge','Lingua Forge uses two independent caching layers to avoid redundant AI API calls. Use the tabs below to inspect and manage each one.'=>'Lingua Forge ใช้ชั้นแคชสองชั้นแยกกันเพื่อหลีกเลี่ยงการเรียก API AI ซ้ำกัน ใช้แท็บด้านล่างเพื่อดูและจัดการแต่ละชั้น','Lingua Forge uses two model tiers per provider:'=>'Lingua Forge ใช้ระดับโมเดลสองระดับต่อผู้ให้บริการ:','Lingua Forge — Quick Translate'=>'Lingua Forge — การแปลด่วน','Lingua Forge — Settings'=>'Lingua Forge — การตั้งค่า','link(s)'=>'ลิงก์','Links'=>'ลิงก์','Load available languages'=>'โหลดภาษาที่ใช้งานได้','Loading…'=>'กำลังโหลด…','Loco Translate stores its custom translations in wp-content/languages/loco/ — a location that can be silently wiped by a WP core update, plugin reinstall, or if Loco Translate itself is removed. Copying files here moves them into the Lingua Forge i18n-overrides directory, which persists through all of those events and is loaded automatically on every request.'=>'Loco Translate เก็บการแปลแบบกำหนดเองไว้ใน wp-content/languages/loco/ — ซึ่งอาจถูกลบโดยการอัปเดตแกน WP การติดตั้งปลั๊กอินใหม่ หรือถ้าหลุดออกจาก Loco Translate เอง การคัดลอกไฟล์ไปที่นี่จะย้ายไปยังไดเรกทอรี Lingua Forge i18n-overrides ซึ่งคงอยู่ตลอดเหตุการณ์เหล่านี้และโหลดโดยอัตโนมัติในทุกคำขอ','Loco Translate — Copy to Safe Storage'=>'Loco Translate — คัดลอกไปยังที่เก็บปลอดภัย','Lowest WordPress capability allowed to trigger AI features. Tightening this on multi-author sites prevents Contributors or trial accounts from running paid AI calls. Override per-feature via the linguaforge_required_capability filter.'=>'ความสามารถของ WordPress ต่ำสุดที่อนุญาตให้เรียกใช้คุณสมบัติ AI การจำกัดนี้บนเว็บไซต์หลายผู้เขียนช่วยป้องกันผู้ร่วมเขียนหรือบัญชีทดลองจากการเรียกใช้ AI แบบชำระเงิน การตั้งค่านี้สามารถปรับเปลี่ยนได้ตามคุณสมบัติผ่านตัวกรอง linguaforge_required_capability','Maintenance'=>'การบำรุงรักษา','Maintenance Tab'=>'แท็บบำรุงรักษา','Make casual'=>'ทำให้เป็นกันเอง','Make concise'=>'ทำให้กระชับ','Make formal'=>'ทำให้เป็นทางการ','Mark citations needed'=>'ทำเครื่องหมายว่าต้องการอ้างอิง','Max context characters'=>'อักขระบริบทสูงสุด','Max hints characters'=>'อักขระคำแนะนำสูงสุด','Max input characters'=>'จำนวนอักขระนำเข้าสูงสุด','Max output tokens'=>'จำนวนโทเค็นผลลัพธ์สูงสุด','Maximum characters accepted from the input field. Default: 8 000.'=>'อักขระสูงสุดที่รับจากช่องป้อนข้อมูล ค่าเริ่มต้น: 8,000','Maximum characters of existing post content passed to the AI as seed context when no Hints are provided. Default: 6 000.'=>'อักขระสูงสุดของเนื้อหาโพสต์ที่มีอยู่ซึ่งส่งต่อให้ AI เป็นบริบทเมล็ดพันธุ์เมื่อไม่มีคำแนะนำ ค่าเริ่มต้น: 6,000','Maximum characters read from the Hints field. Default: 2 000.'=>'อักขระสูงสุดที่อ่านจากช่องคำแนะนำ ค่าเริ่มต้น: 2,000','Maximum number of characters of post content forwarded to the AI. 0 means no limit — the full content is always sent (recommended). Set a non-zero value only if your provider has a tight context window. A warning is written to the PHP error log whenever the content is trimmed.'=>'จำนวนอักขระของเนื้อหาที่ส่งต่อไปยัง AI สูงสุด 0 หมายถึงไม่มีขีดจำกัด — เนื้อหาทั้งหมดจะถูกส่งเสมอ (แนะนำ) ตั้งค่าค่านี้เป็นค่าที่ไม่ใช่ศูนย์เท่านั้นหากผู้ให้บริการของคุณมีขอบเขตบริบทที่แน่นหนา ข้อเตือนจะถูกเขียนลงในบันทึกข้อผิดพลาด PHP เมื่อเนื้อหาถูกตัดออก','Maximum number of tokens the AI may produce in a single translation response. If a translation is silently cut off at the end, increase this value. Default: 16 000.'=>'จำนวนโทเค็นสูงสุดที่ AI อาจผลิตในคำตอบการแปลเดียว หากการแปลถูกตัดออกอย่างเงียบ ๆ ให้เพิ่มค่านี้ ค่าเริ่มต้น: 16,000','Maximum tokens the AI may produce per generation run. Raise this if full articles are being cut off. Default: 8 192.'=>'จำนวนโทเค็นสูงสุดที่ AI อาจผลิตต่อการสร้างแต่ละครั้ง หากเนื้อหาทั้งหมดถูกตัดออก ให้เพิ่มขึ้น ค่าเริ่มต้น: 8,192','Maximum tokens the AI may produce per quick translation. Default: 2 000.'=>'จำนวนโทเค็นสูงสุดที่ AI อาจผลิตต่อการแปลอย่างรวดเร็ว ค่าเริ่มต้น: 2,000','Meta Description'=>'คำอธิบายเมตา','Meta Description, Excerpt Generator'=>'คำอธิบายเมตา, ตัวสร้างคำอธิบายย่อ','Minimum role'=>'ระดับขั้นต่ำ','Missing pattern name or language.'=>'ขาดชื่อแพทเทิร์นหรือภาษา','Mode'=>'โหมด','Model'=>'โมเดล','Model tier'=>'ระดับโมเดล','Models'=>'โมเดล','Models Tab (General)'=>'แท็บโมเดล (ทั่วไป)','Most recent cached block'=>'บล็อกแคชล่าสุด','Most recent cached response'=>'คำตอบแคชล่าสุด','Multilingual routing, SEO meta tags, and AI content tools for WordPress. Combines language detection, URL routing, hreflang, meta descriptions, and AI-powered excerpt, meta, and translation features.'=>'การกำหนดเส้นทางหลายภาษา, แท็กเมตา SEO, และเครื่องมือเนื้อหา AI สำหรับ WordPress รวมการตรวจจับภาษา, การกำหนดเส้นทาง URL, hreflang, คำอธิบายเมตา, และคุณสมบัติย่อ, เมตา, และการแปลที่ขับเคลื่อนด้วย AI.','Name displayed in this language. Leave empty to use the source name.'=>'ชื่อที่แสดงในภาษานี้ ปล่อยว่างไว้เพื่อใช้ชื่อเดิม','Navigation'=>'เมนูนำทาง','Navigation has no content to translate.'=>'ไม่มีเนื้อหาให้แปลในเมนูนำทาง','Navigation not found.'=>'ไม่พบการนำทาง','Navigation posts are translated via the Router tab, not this button.'=>'โพสต์นำทางถูกแปลผ่านแท็บ Router ไม่ใช่ปุ่มนี้','Navigation translation requires an active AI provider. Configure an API key in the API Keys tab.'=>'การแปลเมนูนำทางต้องมีผู้ให้บริการ AI ที่ใช้งานอยู่ ตั้งค่าคีย์ API ในแท็บ API Keys','Navigations'=>'เมนูนำทาง','Network error — could not reach the WordPress AJAX endpoint.'=>'ข้อผิดพลาดเครือข่าย — ไม่สามารถเข้าถึงจุดสิ้นสุด WordPress AJAX ได้','No %s version found in this translation group.'=>'ไม่พบเวอร์ชัน %s ในกลุ่มการแปลนี้','No AI provider configured.'=>'ไม่ได้กำหนดผู้ให้บริการ AI','No AI usage recorded in the selected window (%s). Pick a wider range above.'=>'ยังไม่มีการบันทึกการใช้งาน AI ในช่วงเวลาที่เลือก (%s) เลือกช่วงเวลาที่กว้างขึ้นด้านบน','No AI usage recorded yet. Once an editor runs a translation, generates a meta description, or uses any other AI feature, totals will appear here.'=>'ยังไม่มีการบันทึกการใช้งาน AI เมื่อบรรณาธิการรันการแปล สร้างคำอธิบายเมตา หรือใช้คุณสมบัติ AI อื่น ๆ ยอดรวมจะปรากฏที่นี่','No API key configured for this provider.'=>'ไม่มีคีย์ API ที่กำหนดค่าสำหรับผู้ให้บริการนี้','No built-in instructions — each AI feature uses its own tuned defaults. Fill in the Custom prompt instructions field below to add your own site-wide rules.'=>'ไม่มีคำแนะนำในตัว — แต่ละคุณสมบัติ AI ใช้ค่าที่ตั้งไว้ล่วงหน้าของตัวเอง กรอกช่องคำแนะนำแบบกำหนดเองด้านล่างเพื่อเพิ่มกฎของเว็บไซต์ของคุณเอง','No custom Loco Translate files found yet. They appear here once you save a translation in Loco Translate.'=>'ยังไม่พบไฟล์ Loco Translate แบบกำหนดเอง พวกเขาจะปรากฏที่นี่เมื่อคุณบันทึกการแปลใน Loco Translate','No file was selected.'=>'ยังไม่ได้เลือกไฟล์','No glossary entries match the current filter. Clear the filter to see all entries, or add a new entry below.'=>'ไม่มีรายการคำศัพท์ตรงกับตัวกรองปัจจุบัน ล้างตัวกรองเพื่อดูรายการทั้งหมด หรือเพิ่มรายการใหม่ด้านล่าง','No glossary entries yet. Add one below to start enforcing terminology in translations.'=>'ยังไม่มีรายการคำศัพท์ เพิ่มรายการด้านล่างเพื่อเริ่มบังคับใช้คำศัพท์ในคำแปล','No internal links found to update.'=>'ไม่พบลิงก์ภายในเพื่ออัปเดต','No language-specific template parts found to map.'=>'ไม่พบส่วนเทมเพลตเฉพาะภาษาเพื่อแมป','No navigation references needed updating.'=>'ไม่จำเป็นต้องอัปเดตรายการอ้างอิงการนำทาง','No override files uploaded yet.'=>'ยังไม่ได้อัปโหลดไฟล์แทนที่','No response from provider — check the error log for details.'=>'ไม่มีการตอบสนองจากผู้ให้บริการ — ตรวจสอบบันทึกข้อผิดพลาดเพื่อรายละเอียด','No secondary languages configured. Install a language pack above to enable template scaffolding.'=>'ยังไม่ได้กำหนดภาษาที่สอง ติดตั้งแพ็คภาษาข้างต้นเพื่อเปิดใช้งานการสร้างเทมเพลต','No source content found to translate.'=>'ไม่พบเนื้อหาที่จะแปล','No source page linked yet.'=>'ยังไม่ได้เชื่อมโยงหน้าต้นทาง','No template part references needed updating.'=>'ไม่จำเป็นต้องอัปเดตรายการอ้างอิงของส่วนเทมเพลต','No {lang} translation registered (TRID missing)'=>'ยังไม่ได้ลงทะเบียนการแปล {lang} (TRID หายไป)','Notes'=>'หมายเหตุ','Notice message'=>'ข้อความแจ้งเตือน','Notice settings'=>'การตั้งค่าการแจ้งเตือน','Oldest cached block'=>'บล็อกเก่าแก่ที่สุด','Oldest cached response'=>'คำตอบเก่าแก่ที่สุด','Only .mo files are accepted.'=>'รับเฉพาะไฟล์ .mo เท่านั้น','OpenAI (GPT)'=>'OpenAI (GPT)','Optional context for editors (e.g. "ASIC = Application-Specific Integrated Circuit; preserve in English in technical contexts").'=>'บริบทเพิ่มเติมสำหรับบรรณาธิการ (เช่น "ASIC = ชุดวงจรเฉพาะทาง; คงไว้ในภาษาอังกฤษในบริบททางเทคนิค")','Output'=>'ผลลัพธ์','Output tokens'=>'โทเค็นออก','overridden'=>'โอเวอร์ไรท์แล้ว','Override file deleted.'=>'ลบไฟล์แทนที่แล้ว','Override file uploaded successfully.'=>'อัปโหลดไฟล์แทนที่สำเร็จแล้ว','Overrides the AI preset for Translation and Content Generation on this page. All other features always use the global preset.'=>'แทนที่ชุดพฤติกรรม AI สำหรับการแปลและสร้างเนื้อหาในหน้านี้ ฟีเจอร์อื่น ๆ ทั้งหมดจะใช้ค่าที่ตั้งไว้ทั่วโลกเสมอ','Overrides the AI preset for Translation and Content Generation on this page. Site-wide custom prompt instructions (Settings → Behavior) are always appended to every request regardless of this selection.'=>'แทนที่ชุดพฤติกรรม AI สำหรับการแปลและสร้างเนื้อหาในหน้านี้ คำสั่งแบบกำหนดเองของไซต์ (การตั้งค่า → พฤติกรรม) จะถูกเพิ่มเข้าไปในคำขอทุกครั้งไม่ว่าจะเลือกอย่างไร','Overview'=>'ภาพรวม','Page'=>'หน้า','Part'=>'ส่วนประกอบ','Paste a footnote, sentence, or any snippet here…'=>'วางหมายเหตุเชิงอรรถ ประโยค หรือชิ้นส่วนใด ๆ ที่นี่…','Paste text, or select text in the editor first…'=>'วางข้อความ หรือเลือกข้อความในตัวแก้ไขก่อน…','Paste text, or select text on the page first…'=>'วางข้อความ หรือเลือกข้อความบนหน้าเว็บก่อน…','Paste your API key…'=>'วางคีย์ API ของคุณ…','Path prefix — example.com/de/'=>'คำนำหน้าเส้นทาง — example.com/de/','Pattern'=>'รูปแบบ','Pattern has no content to translate.'=>'แพทเทิร์นไม่มีเนื้อหาให้แปล','Pattern not found.'=>'ไม่พบแพทเทิร์น','Pattern translated and saved. Copy the content into your CPT post via the block editor Pattern inserter or use it as a starting point for a Reusable Block.'=>'แปลแพทเทิร์นและบันทึกแล้ว คัดลอกเนื้อหาไปยังโพสต์ CPT ของคุณผ่านตัวแก้ไขบล็อก Pattern inserter หรือใช้เป็นจุดเริ่มต้นสำหรับบล็อกที่สามารถใช้ซ้ำได้','Pattern translation failed.'=>'การแปลรูปแบบล้มเหลว','Per-post cache for AI-generated translations, meta descriptions, excerpts, and content. Always active — no separate toggle required. Entries are invalidated automatically when the content or AI provider/model changes. Use the toolbar "↺ Re-translate" button or click Clear below to force a fresh API call.'=>'แคชสำหรับการแปล AI, คำอธิบายเมตา, ตัวอย่าง และเนื้อหาในแต่ละโพสต์ เปิดใช้งานตลอด — ไม่ต้องเปิดสวิตช์แยก รายการจะถูกยกเลิกโดยอัตโนมัติเมื่อเนื้อหาหรือผู้ให้บริการ/โมเดล AI เปลี่ยนไป ใช้ปุ่ม "↺ แปลใหม่" บนแถบเครื่องมือหรือคลิก ล้างด้านล่างเพื่อบังคับให้เรียก API ใหม่','Permalink rules flushed successfully.'=>'คำสั่ง permalink ถูกล้างเรียบร้อยแล้ว','Permission denied.'=>'ปฏิเสธการอนุญาต','Persuasive'=>'โน้มน้าวใจ','PHP constant'=>'ค่าคงที่ PHP','Pin terms that must not be translated or must always be rendered in a specific way (e.g. brand names, product names, acronyms). Glossary constraints are injected into every AI translation request for all features: post translation, meta description, excerpt, and FSE template translation.'=>'ปักหมุดคำศัพท์ที่ต้องไม่แปลหรือแปลในแบบเฉพาะ (เช่น ชื่อแบรนด์ ชื่อสินค้า ย่อหน้า) ข้อจำกัดของพจนานุกรมจะถูกแทรกเข้าไปในคำขอแปล AI ทุกฟีเจอร์: การแปลโพสต์ คำอธิบายเมตา ตัวอย่าง และการแปลเทมเพลต FSE','Plain language'=>'ภาษาเรียบง่าย','Please enter some instructions first…'=>'กรุณาใส่คำแนะนำก่อน…','Please enter some text first…'=>'กรุณาใส่ข้อความก่อน…','Post'=>'โพสต์','Post not found.'=>'ไม่พบโพสต์','Post Types'=>'ประเภทโพสต์','Prefilled from excerpt. Edit to override.'=>'เติมข้อมูลล่วงหน้าจากคำอธิบายย่อ แก้ไขเพื่อแทนที่','Primary Language'=>'ภาษาหลัก','Primary language'=>'ภาษาหลัก','Primary language saved.'=>'ภาษาหลักถูกบันทึกแล้ว','Primary language: the language your existing content is written in. All translations are produced from this language; changing it does not move or delete any posts.'=>'ภาษาหลัก: ภาษาที่เนื้อหาเดิมของคุณเขียนอยู่ การเปลี่ยนแปลงนี้จะไม่ย้ายหรือ ลบโพสต์ใด ๆ','Processing…'=>'กำลังดำเนินการ…','Provider'=>'ผู้ให้บริการ','Provider returned no text. Check the WordPress error log for the detailed failure reason.'=>'ผู้ให้บริการไม่ส่งข้อความ กล่องบันทึกข้อผิดพลาดของ WordPress ค้นหาเหตุผลความล้มเหลวโดยละเอียด','Quality'=>'คุณภาพ','Quality (default — Sonnet / GPT-4o / Gemini Pro)'=>'คุณภาพ (ค่าเริ่มต้น — Sonnet / GPT-4o / Gemini Pro)','Quality (Sonnet / GPT-4o / Gemini Pro)'=>'คุณภาพ (Sonnet / GPT-4o / Gemini Pro)','Quality: used for post translation and content generation — higher quality, higher cost.'=>'คุณภาพ: ใช้สำหรับการแปลโพสต์และสร้างเนื้อหา — คุณภาพสูงขึ้น ราคาสูงขึ้น','Quick Translate'=>'แปลด่วน','Quick Translation'=>'การแปลด่วน','Quick Translation is used for snippet/chunk mode — short passages translated on demand from the toolbar, editor, or block popovers. It uses a separate, lighter configuration from the full-page translation to keep responses fast and cost-effective.'=>'การแปลด่วนใช้สำหรับโหมดชิ้นส่วน/ช่วง — ข้อความสั้น ๆ ที่แปลตามคำขอจากแถบเครื่องมือ ตัวแก้ไข หรือป็อปอัปบล็อก มันใช้การตั้งค่าที่เบากว่าการแปลหน้าเต็มเพื่อให้การตอบสนองรวดเร็วและคุ้มค่า','Re-enables Gutenberg\'s canLockBlocks. Useful for editorial templates that need to prevent contributors from moving or deleting specific blocks.'=>'เปิดใช้งานอีกครั้งสามารถLockBlocks ของ Gutenberg ซึ่งมีประโยชน์สำหรับแม่แบบการแก้ไขที่ต้องการป้องกันผู้ร่วมแก้ไขไม่ให้ย้ายหรือ ลบบล็อกเฉพาะ','Re-enables supportsTemplateMode. Core to Full-Site-Editing workflows where post-level template overrides are intentional.'=>'เปิดใช้งาน supportsTemplateMode อีกครั้ง ซึ่งเป็นหัวใจสำคัญของเวิร์กโฟลว์การแก้ไขทั้งไซต์เต็มที่ที่มีการโอเวอร์ไรท์แม่แบบระดับโพสต์โดยเจตนา','Re-generates and updates the cached result.'=>'สร้างใหม่และอัปเดตผลลัพธ์ที่แคชไว้','Re-scan'=>'สแกนใหม่','Re-scanning…'=>'กำลังสแกนใหม่…','Re-translate'=>'แปลใหม่','Redirect visitors to their preferred language based on the browser\'s Accept-Language header'=>'เปลี่ยนเส้นทางผู้เยี่ยมชมไปยังภาษาที่พวกเขาต้องการตาม header Accept-Language ของเบราว์เซอร์','Refine further — e.g. "make it shorter" or "use a formal tone"…'=>'ปรับปรุงเพิ่มเติม — เช่น "ทำให้สั้นลง" หรือ "ใช้โทนทางการ"…','Refine further:'=>'ปรับปรุงเพิ่มเติม:','Refinement'=>'การปรับปรุง (รอบที่ %d)','Refinement failed — please try again.'=>'การปรับปรุงล้มเหลว — กรุณาลองใหม่อีกครั้ง','Refining…'=>'กำลังปรับปรุง…','Regenerates WordPress rewrite rules so URL prefixes, language-specific slugs, and archive rewrites are all in sync. Necessary after changing the primary language or adding new language support.'=>'สร้างกฎ rewrite ของ WordPress ใหม่เพื่อให้ URL, คำสั่งภาษา, และการเขียนซ้ำของคลังข้อมูลเป็นไปในทิศทางเดียวกัน จำเป็นต้องทำหลังจากเปลี่ยนภาษาหลักหรือเพิ่มการสนับสนุนภาษาใหม่','Remove stored key'=>'ลบคีย์ที่จัดเก็บไว้','Report an issue on GitHub'=>'รายงานปัญหาบน GitHub','Request failed — please try again.'=>'คำขอไม่สำเร็จ — กรุณาลองใหม่อีกครั้ง','Request failed.'=>'คำขอไม่สำเร็จ','Request failed. Check your connection.'=>'คำขอไม่สำเร็จ กรุณาตรวจสอบการเชื่อมต่อของคุณ','Request failed. Please try again.'=>'คำขอไม่สำเร็จ กรุณาลองใหม่อีกครั้ง','Requests'=>'คำขอ','Reset'=>'รีเซ็ต','Result will appear here…'=>'ผลลัพธ์จะแสดงที่นี่…','Retranslate'=>'แปลซ้ำ','Retranslating…'=>'กำลังแปลซ้ำ…','Review carefully — links and slugs not updated.'=>'ตรวจสอบอย่างละเอียด — ลิงก์และสลักไม่อัปเดต','Review translation before applying'=>'ตรวจสอบการแปลก่อนนำไปใช้','Revise'=>'แก้ไข','Revision'=>'การแก้ไข','Revision Type'=>'ประเภทของการแก้ไข','Router'=>'เราเตอร์','Router Tab'=>'แท็บเราเตอร์','Save Debug Setting'=>'บันทึกการตั้งค่าการดีบัก','Save Router Settings'=>'บันทึกการตั้งค่าของเราเตอร์','Save Settings'=>'บันทึกการตั้งค่า','Save the post to persist changes.'=>'บันทึกโพสต์เพื่อบันทึกการเปลี่ยนแปลง','Save Uninstall Setting'=>'บันทึกการตั้งค่าการถอนการติดตั้ง','Saved to the meta description field when you apply.'=>'บันทึกลงในช่องคำอธิบายเมตาเมื่อคุณนำไปใช้','Scan failed: '=>'การสแกนล้มเหลว: ','Scan request failed. Please try again.'=>'คำขอการสแกนล้มเหลว กรุณาลองใหม่อีกครั้ง','Scanning posts for broken language links…'=>'กำลังสแกนโพสต์เพื่อหาลิงก์ภาษาที่เสีย…','Search'=>'ค้นหา','Search Results'=>'ผลการค้นหา','Security check failed — file path is not permitted.'=>'การตรวจสอบความปลอดภัยล้มเหลว — เส้นทางไฟล์ไม่ได้รับอนุญาต','Select a language to manage its FSE templates, template parts, and navigation menus.'=>'เลือกภาษาที่ต้องการจัดการเทมเพลต FSE, ส่วนประกอบเทมเพลต, และเมนูนำทาง','Select language'=>'เลือกภาษา','SEO character-count info'=>'ข้อมูลนับอักขระ SEO','Server setup (subdomain)'=>'การตั้งค่าเซิร์ฟเวอร์ (โดเมนย่อย)','Sets the default AI behaviour for all features site-wide. Individual posts can override this for Translation and Content Generation via the Lingua Forge meta box.'=>'กำหนดพฤติกรรม AI เริ่มต้นสำหรับทุกคุณสมบัติในไซต์โดยรวม โพสต์แต่ละโพสต์สามารถโอเวอร์ไรท์ได้สำหรับการแปลและการสร้างเนื้อหาโดยใช้กล่องเมตา Lingua Forge','Settings'=>'การตั้งค่า','Settings saved.'=>'บันทึกการตั้งค่าแล้ว','Show home link'=>'แสดงลิงก์หน้าแรก','Shown when no translation exists for the visitor\'s language.'=>'แสดงเมื่อไม่มีการแปลสำหรับภาษาของผู้เยี่ยมชม','Single'=>'เดียว','Single %s'=>'%s เดียว','Single: %s'=>'เดียว: %s','Site-wide ceiling on AI requests per UTC day (counts both Toolbar translations and block revisions). Counter resets at UTC midnight. Set to 0 to disable the cap.'=>'เพดานของเว็บไซต์สำหรับคำขอ AI ต่อวัน UTC (นับทั้งการแปล Toolbar และการแก้ไขบล็อก) ตัวนับจะรีเซ็ตตอนเที่ยงคืน UTC ตั้งค่าเป็น 0 เพื่อปิดการใช้งานขีดจำกัด','Size'=>'ขนาด','Some link fixes failed.'=>'การแก้ไขลิงก์บางส่วนล้มเหลว','Some nav ref fixes failed.'=>'การแก้ไขอ้างอิงนำทางบางส่วนล้มเหลว','Some part fixes failed.'=>'การแก้ไขส่วนประกอบบางส่วนล้มเหลว','Some parts could not be created.'=>'ไม่สามารถสร้างส่วนประกอบบางรายการได้','Some templates could not be created.'=>'ไม่สามารถสร้างเทมเพลตบางรายการได้','Some translations failed.'=>'การแปลบางส่วนล้มเหลว','Source file not found.'=>'ไม่พบไฟล์ต้นทาง','Source lang'=>'ภาษาแหล่งที่มา','Source language'=>'ภาษาแหล่งที่มา','Source term'=>'คำศัพท์ต้นฉบับ','Standard'=>'มาตรฐาน','Standard uses each feature\'s own tuned temperature: Translation T=0.2 (precise), Quick Translate T=0.4, Content Generator T=0.6 (creative). The other presets apply a single fixed temperature across all features.'=>'การตั้งค่ามาตรฐานใช้ความร้อนที่ปรับแต่งของแต่ละคุณสมบัติ: การแปล T=0.2 (แม่นยำ), การแปลอย่างรวดเร็ว T=0.4, การสร้างเนื้อหา T=0.6 (สร้างสรรค์) การตั้งค่าที่เหลือใช้ความร้อนคงที่เดียวกันในทุกคุณสมบัติ','Status'=>'สถานะ','Status / Actions'=>'สถานะ / การดำเนินการ','Storytelling'=>'การเล่าเรื่อง','Strict-preservation mode for legal, regulatory, medical, or technical content. When on, every AI feature uses a low sampling temperature and appends the addendum below to its system prompt — terminology, article numbers, units, brand names, and regulatory language are preserved verbatim rather than paraphrased.'=>'โหมดการรักษาอย่างเข้มงวดสำหรับเนื้อหาทางกฎหมาย กฎระเบียบ การแพทย์ หรือเทคนิค เมื่อเปิดใช้งาน ฟีเจอร์ AI ทุกตัวจะใช้อุณหภูมิตัวอย่างต่ำและแนบคำอธิบายด้านล่างไปยังคำสั่งระบบ — คำศัพท์ หมายเลขบทความ หน่วย ชื่อแบรนด์ และภาษากฎระเบียบจะถูกเก็บรักษาไว้ตามคำศัพท์โดยตรง แทนที่จะเป็นการปรับเปลี่ยน','Structured Outline'=>'โครงร่างแบบมีโครงสร้าง','Subdomain mode requires your web server to point all language subdomains (e.g. de.example.com) to this WordPress installation. After switching modes, flush permalink rules and clear any caches. If your home URL includes www (e.g. www.example.com), use the lf_base_domain filter to set the bare apex domain so subdomains are constructed correctly.'=>'โหมดซับโดเมนต้องให้เว็บเซิร์ฟเวอร์ของคุณชี้ซับโดเมนภาษาทั้งหมด (เช่น de.example.com) ไปยังการติดตั้ง WordPress นี้ หลังจากเปลี่ยนโหมดแล้ว ให้ล้างกฎ permalink และเคลียร์แคชใด ๆ หาก URL หลักของคุณมี www (เช่น www.example.com) ให้ใช้ตัวกรอง lf_base_domain เพื่อกำหนดโดเมนบนสุดให้ถูกต้องเพื่อให้ซับโดเมนสร้างได้อย่างถูกต้อง','Subdomain — de.example.com/'=>'ซับโดเมน — de.example.com/','Supported providers: Anthropic (Claude), OpenAI (GPT), Google (Gemini). Only one provider is active at a time. Select the active provider on the General tab.'=>'ผู้ให้บริการที่รองรับ: Anthropic (Claude), OpenAI (GPT), Google (Gemini) มีผู้ให้บริการหนึ่งรายเท่านั้นที่ใช้งานอยู่ในแต่ละครั้ง เลือกผู้ให้บริการที่ใช้งานบนแท็บทั่วไป','T=%s'=>'T=%s','T=0.2–0.6, per feature'=>'T=0.2–0.6, ต่อคุณสมบัติ','Target lang'=>'ภาษาเป้าหมาย','Target Language'=>'ภาษาปลายทาง','Target language'=>'ภาษาเป้าหมาย','Target term'=>'คำศัพท์เป้าหมาย','Target: 140–160 chars for optimal SERP display'=>'เป้าหมาย: 140–160 ตัวอักษร สำหรับการแสดงผล SERP ที่ดีที่สุด','Technical'=>'เชิงเทคนิค','Technical / Scientific'=>'เทคนิค / วิทยาศาสตร์','Technical / Scientific instructions'=>'คำแนะนำด้านเทคนิค / วิทยาศาสตร์','Template "%s" already exists.'=>'เทมเพลต "%s" มีอยู่แล้ว','Template "{expected}" does not exist — create it in the Site Editor first.'=>'เทมเพลต "{expected}" ไม่มี — สร้างในตัวแก้ไขไซต์ก่อน','Template has no content.'=>'เทมเพลตไม่มีเนื้อหา','Template mode'=>'โหมดแม่แบบ','Template not found or not stored in the database.'=>'ไม่พบเทมเพลตหรือไม่ได้เก็บไว้ในฐานข้อมูล','Template part "%s" already exists.'=>'ส่วนเทมเพลต "%s" มีอยู่แล้ว','Template part has no content.'=>'ส่วนเทมเพลตไม่มีเนื้อหา','Template part not found or not stored in the database.'=>'ไม่พบส่วนเทมเพลตหรือไม่ได้เก็บไว้ในฐานข้อมูล','Template Parts'=>'ส่วนประกอบเทมเพลต','Templates'=>'เทมเพลต','Test connection'=>'ทดสอบการเชื่อมต่อ','Testing…'=>'กำลังทดสอบ…','Text domain / locale'=>'โดเมนข้อความ / ภูมิภาค','Text to translate'=>'ข้อความที่จะแปล','The API Response Cache stores the raw result of every AI request — translation, meta description, excerpt, and content generation — keyed by a hash of the inputs (content, language pair, provider, model). Subsequent requests with identical inputs are served from the cache with no API call. The cache is different from Translation Memory: Translation Memory operates at the block level and is shared across posts; the API Response Cache operates at the feature level and is keyed per post.'=>'แคชคำตอบ API จัดเก็บผลลัพธ์ดิบของคำขอ AI ทุกคำ — การแปล คำอธิบายเมตา ตัวอย่าง และการสร้างเนื้อหา — โดยใช้แฮชของข้อมูลนำเข้า (เนื้อหา คู่ภาษาที่ใช้ ผู้ให้บริการ โมเดล) คำขอถัดไปที่มีข้อมูลเหมือนกันจะถูกส่งจากแคชโดยไม่เรียก API แคชนี้แตกต่างจากหน่วยความจำการแปล: หน่วยความจำการแปลทำงานในระดับบล็อกและแชร์กันระหว่างโพสต์; แคชคำตอบ API ทำงานในระดับฟีเจอร์และใช้คีย์ต่อโพสต์','The editor did not accept the content — please try again.'=>'บรรณาธิการไม่ยอมรับเนื้อหา — กรุณาลองใหม่อีกครั้ง','The Light tier uses the fast model configured in the Models table above (default: Haiku / Flash). Switch to Quality if you need the same translation accuracy as full-page mode for snippets.'=>'ระดับคุณภาพใช้โมเดลที่รวดเร็วซึ่งกำหนดไว้ในตารางโมเดลด้านบน (ค่าเริ่มต้น: Haiku / Flash) เปลี่ยนเป็นคุณภาพถ้าคุณต้องการความแม่นยำในการแปลเหมือนโหมดเต็มหน้าสำหรับชิ้นส่วนข้อความ','The phrase as it appears in the source text.'=>'วลีตามที่ปรากฏในข้อความต้นฉบับ','The primary language is always served at the root of your site — no URL prefix in path mode, no language subdomain in subdomain mode. All other languages use either a /lang/ path prefix (e.g. example.com/de/) or a language subdomain (e.g. de.example.com), depending on the URL structure setting below.'=>'ภาษาหลักจะให้บริการเสมอที่รากของเว็บไซต์ของคุณ — ไม่มีคำนำหน้า URL ในโหมดเส้นทาง ไม่มีซับโดเมนภาษาในโหมดซับโดเมน ภาษาอื่น ๆ ใช้คำนำหน้าเส้นทาง /lang/ (เช่น example.com/de/) หรือซับโดเมนภาษา (เช่น de.example.com) ขึ้นอยู่กับการตั้งค่าโครงสร้าง URL ด้านล่าง','The source page has no footnotes.'=>'หน้าต้นทางไม่มีหมายเหตุเชิงอรรถ','The upload failed — please try again.'=>'การอัปโหลดล้มเหลว — กรุณาลองใหม่อีกครั้ง','These footnotes come from the source page and are shown here for reference only. Add them to this page using the block editor.'=>'หมายเหตุเชิงอรรถเหล่านี้มาจากหน้าต้นทางและแสดงไว้เพื่ออ้างอิงเท่านั้น เพิ่มเข้าไปในหน้านี้โดยใช้ตัวแก้ไขบล็อก','This is the source page. Footnotes are edited directly in the block editor.'=>'นี่คือหน้าต้นทาง หมายเหตุเชิงอรรถแก้ไขได้โดยตรงในตัวแก้ไขบล็อก','This key is currently supplied by a server %s and cannot be removed here. Enter a new key above to override it with a database value.'=>'คีย์นี้ปัจจุบันได้รับจากเซิร์ฟเวอร์ %s และไม่สามารถลบได้ที่นี่ ใส่คีย์ใหม่ด้านบนเพื่อแทนที่ด้วยค่าจากฐานข้อมูล','Tip: to reset a model to the built-in default, clear the field and save.'=>'เคล็ดลับ: เพื่อรีเซ็ตโมเดลเป็นค่าเริ่มต้นในตัว ให้ล้างช่องและบันทึก','To use a custom encryption secret (instead of the derived wp_salt value), add this to wp-config.php:'=>'เพื่อใช้ความลับการเข้ารหัสแบบกำหนดเอง (แทนค่าที่ได้จาก wp_salt) ให้เพิ่มสิ่งนี้ใน wp-config.php:','Today'=>'วันนี้','Token consumption rolled up by feature, provider, and model. Recorded on every successful AI call; Test Connection pings are deliberately excluded so they don\'t skew the totals. The underlying table aggregates daily — pick a window below to view it.'=>'การใช้ Token รวมตามคุณสมบัติ ผู้ให้บริการ และโมเดล บันทึกบนทุกการเรียกใช้งาน AI ที่สำเร็จ; การทดสอบการเชื่อมต่อจะถูกละเว้นเพื่อไม่ให้บิดเบือนยอดรวม ตารางพื้นฐานจะรวมรายวัน — เลือกช่วงเวลาด้านล่างเพื่อดูข้อมูล','Tone'=>'โทนเสียง','tone'=>'โทนเสียง','Tone:'=>'โทนเสียง:','Too many AI requests. Please retry in %d seconds.'=>'คำขอ AI มากเกินไป กรุณาลองใหม่ใน %d วินาที','Total'=>'รวม','Total tokens'=>'รวมโทเค็น','Translate'=>'แปล','Translate / Revise'=>'แปล / แก้ไข','Translate / Revise block'=>'แปล / แก้ไขบล็อก','Translate all'=>'แปลทั้งหมด','Translate chunk'=>'แปลชิ้นส่วน','Translate Content'=>'แปลเนื้อหา','Translate missing'=>'แปลที่ขาดหาย','Translate page…'=>'แปลหน้า…','Translated content'=>'เนื้อหาที่แปลแล้ว','Translated Names'=>'ชื่อที่แปลแล้ว','Translated title'=>'หัวข้อแปลแล้ว','Translated to:'=>'แปลเป็น: ','Translated. Review in the Site Editor — internal links, navigation URLs, and template slugs are not updated automatically.'=>'แปลแล้ว ตรวจสอบในตัวแก้ไขไซต์ — ลิงก์ภายใน, URL การนำทาง, และชื่อเทมเพลตจะไม่ได้รับการอัปเดตโดยอัตโนมัติ','Translating…'=>'กำลังแปล…','Translation'=>'การแปล','Translation Caching'=>'แคชการแปล','Translation found but permalink could not be generated'=>'พบการแปลแล้วแต่ permalink ไม่สามารถสร้างได้','Translation Limits'=>'ขีดจำกัดการแปล','Translation Limits & Behavior'=>'ข้อจำกัดและพฤติกรรมการแปล','Translation Limits: control which user roles can trigger AI translation, and set a monthly token budget. Exceeding the budget suspends AI calls until the month resets.'=>'ข้อจำกัดการแปล: ควบคุมว่าบทบาทผู้ใช้ใดสามารถเรียกใช้การแปล AI ได้ และตั้งงบประมาณโทเค็นรายเดือน การเกินงบประมาณจะระงับการเรียก AI จนกว่าจะถึงเดือนใหม่','Translation Memory'=>'หน่วยความจำการแปล','Translation Memory caches AI results by content hash, language pair, provider, and model. Editing a post invalidates the cache entry so the next translate call gets a fresh result.'=>'แคชหน่วยความจำการแปลบันทึกผลลัพธ์ AI ตามแฮชเนื้อหา คู่ภาษา ผู้ให้บริการ และโมเดล การแก้ไขโพสต์จะทำให้รายการแคชเป็นโมฆะ เพื่อให้การแปลครั้งถัดไปได้ผลลัพธ์ใหม่','Translation Memory cleared. %d cached block was removed.'=>'หน่วยความจำการแปลถูกล้างแล้ว บล็อกแคช %d ถูกลบออก' . "\0" . '','Translation Memory: stores the full translated post per content hash. Clear it when you want to force a retranslation of all posts regardless of whether their content changed.'=>'หน่วยความจำการแปล: เก็บโพสต์ที่แปลสมบูรณ์ตามแฮชเนื้อหา ล้างข้อมูลเมื่อคุณต้องการบังคับให้แปลซ้ำของโพสต์ทั้งหมดโดยไม่สนใจว่ามีการเปลี่ยนแปลงเนื้อหาหรือไม่','Translation workflow'=>'เวิร์กโฟลว์การแปล','Translation, Content Generator'=>'การแปล, ตัวสร้างเนื้อหา','Type'=>'ประเภท','Uli Hake'=>'Uli Hake','Uninstall Behaviour'=>'การถอนการติดตั้งพฤติกรรม','Uninstall setting saved.'=>'บันทึกการตั้งค่าการถอนการติดตั้งแล้ว','unknown error'=>'ข้อผิดพลาดที่ไม่รู้จัก','Unknown provider.'=>'ผู้ให้บริการไม่รู้จัก','Up'=>'ขึ้นบน','Upload .mo file'=>'อัปโหลดไฟล์ .mo','Upload compiled .mo files to override third-party plugin strings for specific locales — for example, a custom VikBooking translation that uses "apartment" instead of "room". Files must follow the WordPress naming convention: {textdomain}-{locale}.mo (e.g. vikbooking-ca.mo). They are stored in the uploads folder and survive plugin updates.'=>'อัปโหลดไฟล์ .mo ที่คอมไพล์แล้วเพื่อแทนที่ข้อความปลั๊กอินของบุคคลที่สามสำหรับภาษาท้องถิ่นเฉพาะ — ตัวอย่างเช่น การแปล VikBooking แบบกำหนดเองที่ใช้ "อพาร์ตเมนต์" แทน "ห้อง" ไฟล์ต้องเป็นไปตามรูปแบบการตั้งชื่อของ WordPress: {textdomain}-{locale}.mo (เช่น vikbooking-ca.mo) พวกเขาถูกเก็บไว้ในโฟลเดอร์ uploads และอยู่รอดจากการอัปเดตปลั๊กอิน','Upload Override'=>'อัปโหลดการแทนที่','URL could not be mapped to a post — check the link target exists'=>'ไม่สามารถแมป URL ไปยังโพสต์ได้ — ตรวจสอบให้แน่ใจว่ามีเป้าหมายลิงก์อยู่','URL structure'=>'โครงสร้าง URL','URL structure: path-prefix mode (example.com/de/) requires no server changes. Subdomain mode (de.example.com) requires a wildcard DNS record, a wildcard SSL certificate, and a web server configuration change — see the Server Setup guide.'=>'โครงสร้าง URL: โหมดพรีฟิกซ์เส้นทาง (example.com/de/) ไม่ต้องเปลี่ยนเซิร์ฟเวอร์ โหมดซับโดเมน (de.example.com) ต้องมีระเบียน DNS แบบวอล์กการ์ด ใบรับรอง SSL แบบวอล์กการ์ด และการตั้งค่าเซิร์ฟเวอร์ — ดูคำแนะนำการตั้งค่าเซิร์ฟเวอร์','Use the tabs across the top of this page to configure each area. Changes to the Router tab take effect immediately; changes to AI keys and model settings apply to the next AI request.'=>'ใช้แท็บด้านบนของหน้านี้เพื่อกำหนดค่าพื้นที่แต่ละส่วน การเปลี่ยนแปลงแท็บเราเตอร์มีผลทันที; การเปลี่ยนแปลงคีย์ AI และการตั้งค่าโมเดลจะมีผลในการร้องขอ AI ครั้งถัดไป','User-managed terminology table per language pair. Entries are appended to the translation system prompt so the AI uses preferred terms consistently — critical for domain vocabulary ("kWp", "PPA", "interconnection point"), brand names that must not translate, and standardised regulatory phrasing. Both language fields are optional: leave "Source language" blank to apply the entry regardless of which language you are translating from; leave "Target language" blank to apply it to all target languages at once.'=>'ตารางคำศัพท์ที่จัดการโดยผู้ใช้ต่อคู่ภาษา รายการจะถูกเพิ่มเข้าไปในคำสั่งระบบการแปลเพื่อให้ AI ใช้คำศัพท์ที่ต้องการอย่างสม่ำเสมอ — สำคัญสำหรับคำศัพท์เฉพาะทาง ("kWp", "PPA", "จุดเชื่อมต่อ"), ชื่อแบรนด์ที่ไม่ควรแปล และวลีทางกฎระเบียบที่เป็นมาตรฐาน ทั้งสองช่องภาษาทั้งต้นทางและปลายทางเป็นทางเลือก: ปล่อย "ภาษาต้นทาง" ว่างเพื่อใช้รายการนี้ไม่ว่าจะเป็นภาษาที่คุณแปลจากหรือไม่; ปล่อย "ภาษาปลายทาง" ว่างเพื่อใช้กับภาษาปลายทางทั้งหมดพร้อมกัน','Using custom meta description.'=>'ใช้คำอธิบายเมตาที่กำหนดเอง','View'=>'ดู','View built-in default'=>'ดูค่าเริ่มต้นในตัว','View details'=>'ดูรายละเอียด','View Lingua Forge details'=>'ดูรายละเอียด Lingua Forge','Visit plugin site'=>'เยี่ยมชมเว็บไซต์ปลั๊กอิน','Warning:'=>'คำเตือน:','When debug logging is enabled (via the toggle below or by defining LINGUAFORGE_AI_DEBUG in wp-config.php), the Translation and FSE template translation features write their raw AI prompts and responses to disk for troubleshooting. Use this section to monitor that output and clear it once you have what you need — the files can grow quickly on large pages. Configure the destination directory via the linguaforge_debug_dir filter.'=>'เมื่อเปิดใช้งานการบันทึกดีบัก (ผ่านสวิตช์ด้านล่างหรือโดยการกำหนด LINGUAFORGE_AI_DEBUG ใน wp-config.php) ฟีเจอร์แปลและเทมเพลตแปล FSE จะเขียนคำสั่งและคำตอบ AI ดิบลงดิสก์เพื่อการแก้ไขปัญหา ใช้ส่วนนี้เพื่อตรวจสอบผลลัพธ์และลบออกเมื่อคุณมีข้อมูลที่ต้องการ — ไฟล์อาจเติบโตอย่างรวดเร็วบนหน้าขนาดใหญ่ กำหนดปลายทางไดเรกทอรีผ่านตัวกรอง linguaforge_debug_dir','When enabled, first-time visitors with no language cookie and no language prefix in the URL are redirected to the closest matching language version. The redirect is skipped if the browser\'s preferred language is not among the active router languages. Once a visitor selects a language via the switcher, the cookie takes priority and the browser header is ignored on all future visits.'=>'เมื่อเปิดใช้งาน ผู้เยี่ยมชมครั้งแรกที่ไม่มีคุกกี้ภาษาและไม่มีคำนำหน้าใน URL จะถูกเปลี่ยนเส้นทางไปยังเวอร์ชันภาษาที่ใกล้เคียงที่สุด การเปลี่ยนเส้นทางจะข้ามไปถ้าภาษาที่เบราว์เซอร์ชื่นชอบไม่อยู่ในภาษาที่เปิดใช้งานของเราเตอร์ เมื่อผู้เยี่ยมชมเลือกภาษาผ่านตัวสลับภาษา คุกกี้จะมีความสำคัญสูงสุดและ header ของเบราว์เซอร์จะถูกละเว้นในทุกการเยี่ยมชมในอนาคต','Which model tier to use for full-page translation. Quality uses the model configured in the Models table above and is recommended for accurate, long-form translation. Switch to Light only if speed or cost is the priority and the content is short.'=>'ระดับโมเดลที่ใช้สำหรับการแปลหน้าเต็ม คุณภาพใช้โมเดลที่กำหนดในตารางโมเดลด้านบนและแนะนำสำหรับการแปลที่แม่นยำและยาว ควรเปลี่ยนเป็นเบาหากความเร็วหรือค่าใช้จ่ายเป็นสิ่งสำคัญและเนื้อหาสั้น','WP-CLI reference'=>'เอกสารอ้างอิง WP-CLI','Write AI prompts and responses to disk for troubleshooting'=>'เขียนคำสั่ง AI และคำตอบลงดิสก์เพื่อการวินิจฉัย','You can also define keys as constants or environment variables (e.g. in wp-config.php). Those sources are used automatically as a fallback when no database key is stored.'=>'คุณยังสามารถกำหนดคีย์เป็นค่าคงที่หรือค่าตัวแปรสภาพแวดล้อม (เช่นใน wp-config.php) แหล่งข้อมูลเหล่านี้จะถูกใช้โดยอัตโนมัติเป็นตัวเลือกสำรองเมื่อไม่มีคีย์ฐานข้อมูลถูกเก็บไว้','You do not have permission to manage these settings.'=>'คุณไม่มีสิทธิ์จัดการการตั้งค่าเหล่านี้','You do not have permission to read this post.'=>'คุณไม่มีสิทธิ์อ่านโพสต์นี้','{n} stale path(s)'=>'{n} เส้นทางเก่า','— Any source language —'=>'— เลือกภาษาแหล่งที่มา —','— Any target language —'=>'— เลือกภาษาเป้าหมาย —','— Any target —'=>'— เลือกเป้าหมาย —','— Any —'=>'— เลือก —','— auto-detect —'=>'— ตรวจจับอัตโนมัติ —','— select a language —'=>'— เลือกภาษา —','— toggle in Settings → Behavior.'=>'— เปิด/ปิดใน การตั้งค่า → พฤติกรรม','← Back'=>'← ย้อนกลับ','↑ Detected from current post'=>'↑ ตรวจพบจากโพสต์ปัจจุบัน','↺ Re-translate'=>'↺ แปลซ้ำ','↺ Refine'=>'↺ ปรับปรุง','↺ Refresh'=>'↺ รีเฟรช','↺ Refreshing…'=>'↺ กำลังรีเฟรช…','⚠ Borderline'=>'⚠ ขอบเขตเสี่ยง','⚠ No <strong>{lang}</strong> posts found. Make sure all translated posts have their Language meta set to <strong>{lang}</strong> in the Language metabox.'=>'⚠ ไม่พบโพสต์ <strong>{lang}</strong> ใด ๆ ตรวจสอบให้แน่ใจว่าโพสต์ที่แปลแล้วมีเมตา Language ตั้งเป็น <strong>{lang}</strong> ในกล่องเมตา Language','⚠ No changes'=>'⚠ ไม่มีการเปลี่ยนแปลง','⚠ No changes — re-scan?'=>'⚠ ไม่มีการเปลี่ยนแปลง — สแกนใหม่ไหม?','✅ Fixed ({n})'=>'✅ แก้ไขแล้ว ({n})','✅ No broken links or template mismatches found for <strong>{lang}</strong>. Scanned <strong>{scanned}</strong> post(s) and page(s) — all checks passed. Template part links (header, footer, sidebar) are not included here — use the Fix Template Parts button to check those separately.'=>'✅ ไม่พบลิงก์เสียหรือความผิดพลาดของเทมเพลตสำหรับ <strong>{lang}</strong> การสแกนโพสต์และเพจจำนวน <strong>{scanned}</strong> — การตรวจสอบผ่านทั้งหมด ลิงก์ส่วนของเทมเพลต (ส่วนหัว ส่วนท้าย แถบด้านข้าง) ไม่รวมอยู่ที่นี่ — ใช้ปุ่มแก้ไขเทมเพลตเพื่อเช็คแยกต่างหาก','✅ Template fixed'=>'✅ เทมเพลตได้รับการแก้ไขแล้ว','✓ All parts created.'=>'✓ สร้างส่วนประกอบทั้งหมดแล้ว','✓ All templates created.'=>'✓ สร้างเทมเพลตทั้งหมดแล้ว','✓ All translated.'=>'✓ แปลทั้งหมดแล้ว','✓ Configured'=>'กำหนดค่าแล้ว','✓ Connection OK'=>'✓ การเชื่อมต่อเรียบร้อยแล้ว','✓ Content generated — see the overlay to review, refine, and apply.'=>'✓ เนื้อหาถูกสร้างขึ้นแล้ว — ดูที่ซ้อนทับเพื่อทบทวน ปรับปรุง และนำไปใช้','✓ Done'=>'✓ เสร็จสิ้น','✓ Enabled'=>'✓ เปิดใช้งาน','✓ Good length'=>'✓ ความยาวดี','✓ In safe storage'=>'✓ ในที่เก็บปลอดภัย','✓ Language installed.'=>'✓ ติดตั้งภาษาแล้ว','✓ Links fixed.'=>'✓ ลิงก์ได้รับการแก้ไขแล้ว','✓ Nav refs fixed.'=>'✓ การแก้ไขอ้างอิงนำทางแล้ว','✓ Parts fixed.'=>'✓ ส่วนประกอบได้รับการแก้ไขแล้ว','✓ Pattern translated.'=>'✓ รูปแบบแปลแล้ว','✓ Refined — review the updated draft above.'=>'✓ ปรับปรุงแล้ว — ตรวจสอบร่างที่อัปเดตด้านบน','✓ Translation saved'=>'✓ การแปลบันทึกแล้ว','✗ Disabled'=>'✗ ปิดใช้งาน','✗ Error:'=>'✗ ข้อผิดพลาด:','✗ Failed:'=>'✗ ล้มเหลว:','✗ Not configured'=>'ยังไม่ได้กำหนดค่า','✗ Too long'=>'✗ ยาวเกินไป','✗ Too short'=>'✗ สั้นเกินไป','❌ Failed'=>'❌ ล้มเหลว','📄 Wrong template'=>'📄 เทมเพลตผิด','📍 Stale path (page moved)'=>'📍 เส้นทางเก่า (หน้าเคลื่อนย้าย)']];
